sys_script_include.script:
var LocalRatingProvider = Class.create();
LocalRatingProvider.prototype = {

    initialize: function () {},

    // RatingProvider contract: rate(quoteOptionLineId) -> result object, and the
    // line is updated. Technical premium = sum of the line's selected coverage
    // premiums (already priced from the product catalogue / rate tables);
    // commercial = technical + the underwriter's discretionary adjustment.
    rate: function (lineId) {
        var line = new GlideRecord(Constants.TABLE.QUOTE_OPTION_LINE);
        if (!line.get(lineId))
            throw new Error('[LocalRatingProvider] quote_option_line not found: ' + lineId);

        var technical = 0;
        var cov = new GlideRecord(Constants.TABLE.QUOTE_OPTION_COVERAGE);
        cov.addQuery('quote_option_line', lineId);
        cov.addQuery('selected', true);
        cov.query();
        while (cov.next())
            technical += parseFloat(cov.getValue('premium')) || 0;

        var adjustment = parseFloat(line.getValue('adjustment_amount')) || 0;
        var commercial = technical + adjustment;
        var commissionRate = parseFloat(line.getValue('commission_rate')) || 0;
        var commission = this._round(commercial * commissionRate / 100);

        var taxes = 0;
        var tf = new GlideAggregate(Constants.TABLE.QUOTE_TAX_FEE);
        tf.addQuery('quote_option_line', lineId);
        tf.addAggregate('SUM', 'amount');
        tf.query();
        if (tf.next())
            taxes = parseFloat(tf.getAggregate('SUM', 'amount')) || 0;

        var result = {
            technical_premium: this._round(technical),
            commercial_premium: this._round(commercial),
            rate_adequacy: technical > 0 ? this._round(commercial / technical * 100) : '',
            commission_amount: commission,
            tax_fee_total: this._round(taxes),
            total_premium: this._round(commercial + taxes)
        };
        for (var k in result) {
            if (result.hasOwnProperty(k))
                line.setValue(k, result[k]);
        }
        line.setValue('rated_on', new GlideDateTime());
        line.setValue('status', Constants.CHOICE.QUOTE_OPTION_STATUS.ACTIVE);
        line.update();
        return result;
    },

    // Re-rates every line of a quote option and rolls the totals up onto it.
    rateOption: function (quoteOptionId) {
        var total = 0, written = 0;
        var line = new GlideRecord(Constants.TABLE.QUOTE_OPTION_LINE);
        line.addQuery('quote_option', quoteOptionId);
        line.query();
        while (line.next()) {
            var r = this.rate(line.getUniqueValue());
            total += r.total_premium;
            written += r.commercial_premium;
        }
        var qo = new GlideRecord(Constants.TABLE.QUOTE_OPTION);
        if (qo.get(quoteOptionId)) {
            qo.setValue('written_premium', this._round(written));
            qo.setValue('total_premium', this._round(total));
            qo.update();
        }
        return { written_premium: this._round(written), total_premium: this._round(total) };
    },

    _round: function (n) {
        return Math.round((parseFloat(n) || 0) * 100) / 100;
    },

    type: 'LocalRatingProvider'
};
